function main(): void {
  console.log(new Date("01/01/2024").getTime() === new Date(2024, 0, 1).getTime());
  console.log(new Date("12/25/2024 10:30 PM").getTime() === new Date(2024, 11, 25, 22, 30).getTime());
  console.log(new Date("1 January 2024 10:00").getTime() === new Date(2024, 0, 1, 10, 0).getTime());
  console.log(new Date("Jan 1, 2024").getTime() === new Date(2024, 0, 1).getTime());
  console.log(new Date("02/30/2024").getTime() === new Date(2024, 1, 30).getTime());
  console.log(new Date("2030-02-30").toISOString(), new Date("2023-02-29").toISOString(), new Date("2024-04-31").toISOString());
  console.log(new Date("2024-02-30T10:00:00Z").toISOString(), new Date("2024-02-31T10:00:00.5+02:00").toISOString());
  console.log(new Date("2024-01-01T10:00:00+0530").toISOString(), new Date("12/25/2024 10:30 +0530").toISOString(), new Date("Jan 1 2024 10:00 PST").toISOString());
  console.log(Date.parse("2024-02-32"), Date.parse("2024-01-00"), Date.parse("13/01/2024"), Date.parse("Jan 32 2024"), Date.parse("2024-01-01T24:00:01"), Date.parse("12:00"));
}
